INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1035, '数学', '三年级', 'apply', 3, '{"stem": "思维拓展：小明全家今年7月外出旅游5天，这5天的日期数的和是80。请算一算，小明家外出旅游的日期是哪几天？（10分）"}', '7月14日~7月18日', '连续5天日期和=中间日×5; 80÷5=16(中间日); 16-2=14, 16-1=15, 16, 16+1=17, 16+2=18', 'jsj3_sx_v110', '["jsj3_sx","U5","p071","think_01"]', 1, NULL);